import { AnimatedCounter } from "@/components/ui/AnimatedCounter";
import { Stagger, StaggerItem } from "@/components/ui/Reveal";
import { Section } from "@/components/ui/Section";
import { SectionHeading } from "@/components/ui/SectionHeading";
import type { SayaclarVeri } from "@/lib/types";
import type { BlokProps } from "./types";

export default function Sayaclar({ veri, blokId }: BlokProps<SayaclarVeri>) {
  const baslikId = `${blokId}-baslik`;
  return (
    <Section arka_plan={veri.arka_plan} padding="kucuk" aria-labelledby={veri.baslik ? baslikId : undefined}>
      <SectionHeading baslik={veri.baslik} baslikId={baslikId} className="mb-10 md:mb-12" />
      <Stagger as="dl" className="grid grid-cols-2 gap-6 lg:grid-cols-4">
        {veri.ogeler.map((o, i) => (
          <StaggerItem key={i} className="flex flex-col-reverse rounded-kart border border-zemin-cizgi bg-zemin-kart p-6 text-center">
            <dt className="mt-2 text-sm text-zemin-soluk">{o.etiket}</dt>
            <dd className="font-display text-4xl font-bold text-zemin-baslik md:text-5xl">
              <AnimatedCounter deger={o.deger} onek={o.onek} sonek={o.sonek} />
            </dd>
          </StaggerItem>
        ))}
      </Stagger>
    </Section>
  );
}
