import { Icon } from "@/components/ui/Icon";
import { Reveal } from "@/components/ui/Reveal";
import { Section } from "@/components/ui/Section";
import type { VurguBandiVeri } from "@/lib/types";
import { cn } from "@/lib/utils";
import type { BlokProps } from "./types";

export default function VurguBandi({ veri, blokId }: BlokProps<VurguBandiVeri>) {
  const kirmizi = veri.stil === "kirmizi";
  const koyu = veri.stil === "koyu";
  const baslikId = `${blokId}-baslik`;
  return (
    <Section arka_plan={koyu ? "koyu" : "acik"} padding="kucuk" genislik="orta" aria-labelledby={baslikId}>
      <Reveal
        className={cn(
          "relative overflow-hidden rounded-panel p-8 md:p-12",
          kirmizi && "bg-primary-aa text-white shadow-cta",
          koyu && "border border-white/10 bg-dark-2",
          !kirmizi && !koyu && "border border-primary/20 bg-primary/5",
        )}
      >
        <div className="flex flex-col gap-6 md:flex-row md:items-start">
          <span
            className={cn(
              "inline-flex size-14 shrink-0 items-center justify-center rounded-2xl",
              kirmizi ? "bg-white/15" : "bg-primary/10",
            )}
          >
            <Icon ad={veri.ikon} boyut={30} className={kirmizi ? "text-white" : "text-primary"} />
          </span>
          <div>
            <h2 id={baslikId} className={cn("text-2xl font-bold md:text-3xl", kirmizi ? "text-white" : "text-zemin-baslik")}>
              {veri.baslik}
            </h2>
            {veri.metin ? (
              <p className={cn("mt-4 text-lg leading-relaxed", kirmizi ? "text-white/85" : "text-zemin-soluk")}>
                {veri.metin}
              </p>
            ) : null}
            {veri.vurgu_cumlesi ? (
              <p className={cn("mt-6 font-display text-xl font-semibold", kirmizi ? "text-white" : "text-zemin-vurgu")}>
                {veri.vurgu_cumlesi}
              </p>
            ) : null}
          </div>
        </div>
      </Reveal>
    </Section>
  );
}
