/**
 * zengin_metin — Zengin Metin (KVKK, çerez politikası, serbest metin). CONTRACT §8.
 * `icerik_html` backend'de nh3 ile sanitize edilmiştir; `.prose-eisa` ile biçimlenir.
 * Sözleşme: src/blocks/README.md
 */

import { Reveal } from "@/components/ui/Reveal";
import { Section } from "@/components/ui/Section";
import type { ZenginMetinVeri } from "@/lib/types";
import { cn } from "@/lib/utils";
import type { BlokProps } from "./types";

export default function ZenginMetin({ veri, blokId }: BlokProps<ZenginMetinVeri>) {
  const genis = veri.genislik === "genis";
  const baslikId = `${blokId}-baslik`;
  return (
    <Section arka_plan="acik" genislik={genis ? "normal" : "dar"} aria-labelledby={veri.baslik ? baslikId : undefined}>
      <Reveal>
        {veri.baslik ? (
          <h2 id={baslikId} className="mb-8 text-3xl font-bold text-zemin-baslik md:text-4xl">
            {veri.baslik}
          </h2>
        ) : null}
        {veri.son_guncelleme ? (
          <p className="mb-8 inline-flex rounded-full bg-gri px-4 py-1.5 text-sm text-zemin-soluk">
            Son güncelleme: {veri.son_guncelleme}
          </p>
        ) : null}
        <div
          className={cn("prose-eisa", genis && "prose-eisa-genis")}
          // İçerik backend'de nh3 ile sanitize edilir (CONTRACT §5).
          dangerouslySetInnerHTML={{ __html: veri.icerik_html || "" }}
        />
      </Reveal>
    </Section>
  );
}
