import { ButonLink } from "@/components/ui/ButonLink";
import { GradientBackdrop, NoiseOverlay } from "@/components/ui/Dekor";
import { Reveal } from "@/components/ui/Reveal";
import { Section } from "@/components/ui/Section";
import type { CtaBannerVeri } from "@/lib/types";
import { cn } from "@/lib/utils";
import type { BlokProps } from "./types";

export default function CtaBanner({ veri, blokId }: BlokProps<CtaBannerVeri>) {
  const kirmizi = veri.stil === "kirmizi";
  const baslikId = `${blokId}-baslik`;
  return (
    <Section arka_plan="acik" padding="kucuk" aria-labelledby={baslikId}>
      <Reveal>
        <div
          data-zemin="koyu"
          className={cn(
            "relative isolate overflow-hidden rounded-panel px-8 py-14 text-center md:px-16 md:py-20",
            kirmizi ? "bg-primary-aa" : "bg-dark",
          )}
        >
          <GradientBackdrop varyant={kirmizi ? "kirmizi" : "koyu"} izgara={!kirmizi} />
          <NoiseOverlay />
          {veri.rozet ? (
            <p className="eyebrow mb-4 inline-flex rounded-full bg-white/10 px-4 py-1.5 text-white">{veri.rozet}</p>
          ) : null}
          <h2 id={baslikId} className="mx-auto max-w-3xl text-3xl font-bold text-white md:text-5xl">
            {veri.baslik}
          </h2>
          {veri.metin ? <p className="mx-auto mt-5 max-w-2xl text-lg text-white/80">{veri.metin}</p> : null}
          {veri.butonlar?.length ? (
            <div className="mt-10 flex flex-wrap items-center justify-center gap-4">
              {veri.butonlar.map((b, i) => (
                <ButonLink
                  key={i}
                  buton={kirmizi && b.stil === "birincil" ? { ...b, stil: "ikincil" } : b}
                  boyut="buyuk"
                />
              ))}
            </div>
          ) : null}
        </div>
      </Reveal>
    </Section>
  );
}
