import { Icon } from "@/components/ui/Icon";
import { Stagger, StaggerItem } from "@/components/ui/Reveal";
import { Section } from "@/components/ui/Section";
import { SectionHeading } from "@/components/ui/SectionHeading";
import type { OzellikKartlariVeri } from "@/lib/types";
import { cn } from "@/lib/utils";
import type { BlokProps } from "./types";

const SUTUN: Record<number, string> = {
  2: "md:grid-cols-2",
  3: "md:grid-cols-2 lg:grid-cols-3",
  4: "sm:grid-cols-2 lg:grid-cols-4",
};

export default function OzellikKartlari({ veri, blokId }: BlokProps<OzellikKartlariVeri>) {
  const sutun = Number(veri.sutun) || 3;
  const baslikId = `${blokId}-baslik`;
  return (
    <Section arka_plan={veri.arka_plan} aria-labelledby={veri.baslik ? baslikId : undefined}>
      <SectionHeading
        ust_baslik={veri.ust_baslik}
        baslik={veri.baslik}
        aciklama={veri.aciklama}
        baslikId={baslikId}
      />
      <Stagger as="ul" className={cn("grid gap-6", SUTUN[sutun] ?? SUTUN[3])}>
        {veri.kartlar.map((k, i) => (
          <StaggerItem
            as="li"
            key={i}
            className="rounded-kart border border-zemin-cizgi bg-zemin-kart p-7 shadow-kart transition-shadow duration-300 hover:shadow-kart-hover"
          >
            <span className="inline-flex size-12 items-center justify-center rounded-xl bg-primary/10">
              <Icon ad={k.ikon} boyut={28} className="text-primary" />
            </span>
            <h3 className="mt-5 text-xl font-semibold text-zemin-baslik">{k.baslik}</h3>
            <p className="mt-3 leading-relaxed text-zemin-soluk">{k.metin}</p>
          </StaggerItem>
        ))}
      </Stagger>
    </Section>
  );
}
