import { LinkedinLogoIcon } from "@phosphor-icons/react/dist/ssr/LinkedinLogo";
import { MediaImage } from "@/components/ui/MediaImage";
import { Stagger, StaggerItem } from "@/components/ui/Reveal";
import { Section } from "@/components/ui/Section";
import { SectionHeading } from "@/components/ui/SectionHeading";
import type { EkipVeri } from "@/lib/types";
import type { BlokProps } from "./types";

function basHarfler(ad: string): string {
  return ad
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((p) => p.charAt(0).toLocaleUpperCase("tr-TR"))
    .join("");
}

export default function Ekip({ veri, blokId }: BlokProps<EkipVeri>) {
  const baslikId = `${blokId}-baslik`;
  return (
    <Section arka_plan="acik" aria-labelledby={baslikId}>
      <SectionHeading ust_baslik={veri.ust_baslik} baslik={veri.baslik} aciklama={veri.aciklama} baslikId={baslikId} />
      <Stagger as="ul" className="flex flex-wrap justify-center gap-6">
        {veri.kisiler.map((k, i) => (
          <StaggerItem
            as="li"
            key={i}
            className="w-full max-w-sm rounded-kart border border-zemin-cizgi bg-zemin-kart p-8 text-center shadow-kart"
          >
            <div className="relative mx-auto size-28 overflow-hidden rounded-full bg-dark">
              <MediaImage medya={k.foto} fill sizes="112px" className="object-cover">
                <span aria-hidden className="flex h-full items-center justify-center font-display text-3xl font-bold text-white">
                  {basHarfler(k.ad_soyad)}
                </span>
              </MediaImage>
            </div>
            <h3 className="mt-6 text-xl font-semibold text-zemin-baslik">{k.ad_soyad}</h3>
            <p className="mt-1 text-sm font-medium text-zemin-vurgu">{k.unvan}</p>
            {k.biyografi ? <p className="mt-4 text-sm leading-relaxed text-zemin-soluk">{k.biyografi}</p> : null}
            {k.linkedin ? (
              <a
                href={k.linkedin}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={`${k.ad_soyad} LinkedIn profili (yeni sekmede açılır)`}
                className="mt-5 inline-flex size-10 items-center justify-center rounded-full border border-zemin-cizgi text-zemin-soluk transition-colors hover:border-primary hover:text-primary"
              >
                <LinkedinLogoIcon aria-hidden size={20} />
              </a>
            ) : null}
          </StaggerItem>
        ))}
      </Stagger>
    </Section>
  );
}
