/**
 * logo_bandi — Logo Bandı. CONTRACT §8.
 * STUB: blok ajanı tarafından zenginleştirilecek (kayan marquee — `animate-marquee` utility hazır).
 * Logo yoksa `bos_mesaj` gösterilir. Sözleşme: src/blocks/README.md
 */

import { MediaImage } from "@/components/ui/MediaImage";
import { Reveal } from "@/components/ui/Reveal";
import { Section } from "@/components/ui/Section";
import { SectionHeading } from "@/components/ui/SectionHeading";
import type { LogoBandiVeri } from "@/lib/types";
import type { BlokProps } from "./types";

export default function LogoBandi({ veri, blokId }: BlokProps<LogoBandiVeri>) {
  const baslikId = `${blokId}-baslik`;
  const logolar = (veri.logolar ?? []).filter((l) => l.gorsel?.yol);
  return (
    <Section arka_plan="acik" padding="kucuk" aria-labelledby={veri.baslik ? baslikId : undefined}>
      <SectionHeading baslik={veri.baslik} baslikId={baslikId} className="mb-8 md:mb-10" />
      {logolar.length ? (
        <ul className="flex flex-wrap items-center justify-center gap-x-12 gap-y-8">
          {logolar.map((l, i) => (
            <li key={i} className="relative h-12 w-36 opacity-70 grayscale transition hover:opacity-100 hover:grayscale-0">
              {l.url ? (
                <a href={l.url} target="_blank" rel="noopener noreferrer" aria-label={`${l.ad} (yeni sekmede açılır)`}>
                  <MediaImage medya={l.gorsel} alt={l.ad} fill sizes="144px" className="object-contain" />
                </a>
              ) : (
                <MediaImage medya={l.gorsel} alt={l.ad} fill sizes="144px" className="object-contain" />
              )}
            </li>
          ))}
        </ul>
      ) : veri.bos_mesaj ? (
        <Reveal className="mx-auto max-w-2xl rounded-kart border border-dashed border-zemin-cizgi p-8 text-center text-zemin-soluk">
          {veri.bos_mesaj}
        </Reveal>
      ) : null}
    </Section>
  );
}
