import { EnvelopeSimpleIcon } from "@phosphor-icons/react/dist/ssr/EnvelopeSimple";
import { PhoneIcon } from "@phosphor-icons/react/dist/ssr/Phone";
import { Icon } from "@/components/ui/Icon";
import { Reveal } from "@/components/ui/Reveal";
import { Section } from "@/components/ui/Section";
import { SectionHeading } from "@/components/ui/SectionHeading";
import { getSite } from "@/lib/api";
import type { BasvuruFormuVeri } from "@/lib/types";
import { slugYolu } from "@/lib/utils";
import { BasvuruFormIstemci } from "./_parcalar/BasvuruFormIstemci";
import type { BlokProps } from "./types";

export default async function BasvuruFormu({ veri, blokId }: BlokProps<BasvuruFormuVeri>) {
  const baslikId = `${blokId}-baslik`;
  const { ayarlar } = await getSite();
  const kvkkHref = slugYolu(veri.kvkk_sayfa_slug || "kvkk");
  const yanPanel = Boolean(veri.maddeler?.length || veri.iletisim_bilgisi_goster);

  return (
    <Section arka_plan="gri" aria-labelledby={baslikId}>
      <SectionHeading ust_baslik={veri.ust_baslik} baslik={veri.baslik} aciklama={veri.aciklama} baslikId={baslikId} />
      <div className={yanPanel ? "grid gap-10 lg:grid-cols-5" : "mx-auto max-w-3xl"}>
        {yanPanel ? (
          <Reveal className="space-y-4 lg:col-span-2">
            {veri.maddeler?.map((m, i) => (
              <div key={i} className="flex gap-4 rounded-kart border border-zemin-cizgi bg-zemin-kart p-5">
                <Icon ad={m.ikon} boyut={28} className="shrink-0 text-primary" />
                <div>
                  <h3 className="font-semibold text-zemin-baslik">{m.baslik}</h3>
                  <p className="mt-1 text-sm text-zemin-soluk">{m.metin}</p>
                </div>
              </div>
            ))}
            {veri.iletisim_bilgisi_goster ? (
              <div className="rounded-kart border border-zemin-cizgi bg-zemin-kart p-5">
                <h3 className="font-semibold text-zemin-baslik">İletişim bilgileri</h3>
                <ul className="mt-3 space-y-2 text-sm">
                  {ayarlar.eposta ? (
                    <li>
                      <a href={`mailto:${ayarlar.eposta}`} className="inline-flex items-center gap-2 text-zemin-metin hover:text-zemin-vurgu">
                        <EnvelopeSimpleIcon aria-hidden size={18} className="text-primary" />
                        {ayarlar.eposta}
                      </a>
                    </li>
                  ) : null}
                  {ayarlar.telefon ? (
                    <li>
                      <a
                        href={`tel:${ayarlar.telefon.replace(/[^\d+]/g, "")}`}
                        className="inline-flex items-center gap-2 text-zemin-metin hover:text-zemin-vurgu"
                      >
                        <PhoneIcon aria-hidden size={18} className="text-primary" />
                        {ayarlar.telefon}
                      </a>
                    </li>
                  ) : null}
                  {ayarlar.adres ? <li className="whitespace-pre-line text-zemin-soluk">{ayarlar.adres}</li> : null}
                </ul>
              </div>
            ) : null}
          </Reveal>
        ) : null}
        <Reveal gecikme={0.1} className={yanPanel ? "lg:col-span-3" : undefined}>
          <div className="rounded-panel border border-zemin-cizgi bg-zemin-kart p-6 shadow-kart md:p-10">
            <BasvuruFormIstemci tip={veri.form_tipi} basariMesaji={veri.basari_mesaji} kvkkHref={kvkkHref} />
          </div>
        </Reveal>
      </div>
    </Section>
  );
}
