import { ButonGrubu } from "@/components/ui/ButonLink";
import { Icon } from "@/components/ui/Icon";
import { MediaImage } from "@/components/ui/MediaImage";
import { Paragraflar } from "@/components/ui/Paragraflar";
import { Reveal } from "@/components/ui/Reveal";
import { Section } from "@/components/ui/Section";
import { SectionHeading } from "@/components/ui/SectionHeading";
import type { GorselMetinVeri } from "@/lib/types";
import { cn } from "@/lib/utils";
import type { BlokProps } from "./types";

export default function GorselMetin({ veri, blokId, ilk }: BlokProps<GorselMetinVeri>) {
  const solda = veri.gorsel_konumu === "sol";
  const baslikId = `${blokId}-baslik`;
  return (
    <Section arka_plan={veri.arka_plan} aria-labelledby={baslikId}>
      <div className="grid items-center gap-12 lg:grid-cols-2 lg:gap-16">
        <Reveal yon={solda ? "sag" : "sol"} className={cn(solda && "lg:order-2")}>
          <SectionHeading
            ust_baslik={veri.ust_baslik}
            baslik={veri.baslik}
            baslikId={baslikId}
            hizalama="sol"
            animasyon={false}
            className="mb-6 md:mb-6"
          />
          <Paragraflar metin={veri.metin} className="text-lg leading-relaxed text-zemin-soluk" />
          {veri.maddeler?.length ? (
            <ul className="mt-8 grid gap-3 sm:grid-cols-2">
              {veri.maddeler.map((m, i) => (
                <li key={i} className="flex items-center gap-3 text-zemin-metin">
                  <Icon ad={m.ikon} boyut={22} className="shrink-0 text-primary" />
                  <span className="font-medium">{m.metin}</span>
                </li>
              ))}
            </ul>
          ) : null}
          <ButonGrubu butonlar={veri.butonlar} className="mt-8" />
        </Reveal>

        <Reveal yon={solda ? "sol" : "sag"} gecikme={0.1} className={cn(solda && "lg:order-1")}>
          <div className="relative aspect-[4/3] overflow-hidden rounded-panel border border-zemin-cizgi bg-dark shadow-kart-hover">
            <MediaImage medya={veri.gorsel} fill sizes="(min-width: 1024px) 50vw, 100vw" priority={ilk} className="object-cover">
              {/* Görsel yoksa: STUB dekoratif yer tutucu */}
              <div aria-hidden className="doku-izgara flex h-full items-center justify-center">
                <Icon ad="Monitor" boyut={72} className="text-white/30" />
              </div>
            </MediaImage>
          </div>
        </Reveal>
      </div>
    </Section>
  );
}
