/**
 * kazanc_hesaplayici — Kazanç Hesaplayıcı. CONTRACT §8.
 * STUB: blok ajanı tarafından yazılacak (client adacığı: kaydırıcı → kademe seçimi
 * `etkilesim_min <= v <= etkilesim_max` olan İLK kademe; v tüm kademelerin üstündeyse son kademe).
 * Rakamlar "örnek senaryo/potansiyel"dir; `uyari_notu` her zaman görünür olmalı.
 * Sözleşme: src/blocks/README.md
 */

import { Reveal } from "@/components/ui/Reveal";
import { Section } from "@/components/ui/Section";
import { SectionHeading } from "@/components/ui/SectionHeading";
import type { KazancHesaplayiciVeri } from "@/lib/types";
import { paraFormatla, sayiFormatla } from "@/lib/utils";
import type { BlokProps } from "./types";

export default function KazancHesaplayici({ veri, blokId }: BlokProps<KazancHesaplayiciVeri>) {
  const pb = veri.para_birimi || "TL";
  const baslikId = `${blokId}-baslik`;
  return (
    <Section arka_plan="acik" aria-labelledby={baslikId}>
      <SectionHeading ust_baslik={veri.ust_baslik} baslik={veri.baslik} aciklama={veri.aciklama} baslikId={baslikId} />
      {veri.tablo_goster !== false && veri.kademeler?.length ? (
        <Reveal className="overflow-x-auto rounded-kart border border-zemin-cizgi bg-zemin-kart shadow-kart">
          <table className="w-full min-w-[40rem] text-left text-sm">
            <caption className="sr-only">Örnek etkileşim ve satış potansiyeli tablosu</caption>
            <thead className="bg-gri text-zemin-baslik">
              <tr>
                <th scope="col" className="p-4 font-semibold">Günlük etkileşim</th>
                <th scope="col" className="p-4 text-right font-semibold">Günlük satış</th>
                <th scope="col" className="p-4 text-right font-semibold">Aylık satış</th>
                <th scope="col" className="p-4 text-right font-semibold">Aylık ciro</th>
                <th scope="col" className="p-4 text-right font-semibold">Aylık kâr potansiyeli</th>
              </tr>
            </thead>
            <tbody>
              {veri.kademeler.map((k, i) => (
                <tr key={i} className="border-t border-zemin-cizgi">
                  <th scope="row" className="p-4 font-medium text-zemin-baslik">
                    {k.etkilesim_min}-{k.etkilesim_max}
                  </th>
                  <td className="p-4 text-right tabular-nums">{sayiFormatla(k.gunluk_satis)}</td>
                  <td className="p-4 text-right tabular-nums">{sayiFormatla(k.aylik_satis)}</td>
                  <td className="p-4 text-right tabular-nums">{paraFormatla(k.aylik_ciro, pb)}</td>
                  <td className="p-4 text-right font-semibold text-zemin-vurgu tabular-nums">{paraFormatla(k.aylik_kar, pb)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </Reveal>
      ) : null}
      {veri.uyari_notu ? (
        <p className="mx-auto mt-6 max-w-3xl text-center text-sm text-zemin-soluk italic">* {veri.uyari_notu}</p>
      ) : null}
    </Section>
  );
}
