import { Stagger, StaggerItem } from "@/components/ui/Reveal";
import { Section } from "@/components/ui/Section";
import { SectionHeading } from "@/components/ui/SectionHeading";
import type { SurecAdimlariVeri } from "@/lib/types";
import type { BlokProps } from "./types";

export default function SurecAdimlari({ veri, blokId }: BlokProps<SurecAdimlariVeri>) {
  const baslikId = `${blokId}-baslik`;
  return (
    <Section arka_plan={veri.arka_plan} aria-labelledby={baslikId}>
      <SectionHeading ust_baslik={veri.ust_baslik} baslik={veri.baslik} aciklama={veri.aciklama} baslikId={baslikId} />
      <Stagger as="ol" className="grid gap-6 sm:grid-cols-2 lg:grid-cols-4">
        {veri.adimlar.map((a, i) => (
          <StaggerItem as="li" key={i} className="relative rounded-kart border border-zemin-cizgi bg-zemin-kart p-7 shadow-kart">
            <span className="font-display text-5xl font-bold text-primary/20">{String(i + 1).padStart(2, "0")}</span>
            <h3 className="mt-3 text-lg font-semibold text-zemin-baslik">{a.baslik}</h3>
            <p className="mt-2 leading-relaxed text-zemin-soluk">{a.metin}</p>
          </StaggerItem>
        ))}
      </Stagger>
    </Section>
  );
}
